"use client"

import * as React from "react"
import { NumberField as NumberFieldPrimitive } from "@base-ui/react/number-field"
import { cn } from "cn"
import { MinusIcon, PlusIcon } from "lucide-react"

import { InputGroupAddon, InputGroupButton } from "@/components/ui/input-group"

function NumberField({
  className,
  disabled,
  ...props
}: NumberFieldPrimitive.Root.Props) {
  return (
    <NumberFieldPrimitive.Root
      data-slot="number-field"
      data-disabled={disabled ? "true" : undefined}
      role="group"
      disabled={disabled}
      className={cn(
        "bg-input/50 border-transparent has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-ring/30 has-[[data-slot][aria-invalid=true]]:ring-destructive/20 has-[[data-slot][aria-invalid=true]]:border-destructive dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40 h-8 rounded-2xl border transition-[color,box-shadow] duration-200 in-data-[slot=combobox-content]:focus-within:border-inherit in-data-[slot=combobox-content]:focus-within:ring-0 has-[[data-slot=input-group-control]:focus-visible]:ring-3 has-[[data-slot][aria-invalid=true]]:ring-3 has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-end]]:[&>input]:pt-3 has-[>[data-align=block-start]]:[&>input]:pb-3 has-[>[data-align=inline-end]]:[&>[data-slot=input-group-control]]:pr-1.5 has-[>[data-align=inline-start]]:[&>[data-slot=input-group-control]]:pl-1.5 group/input-group relative flex w-32 min-w-0 items-center outline-none",
        className
      )}
      {...props}
    />
  )
}

function NumberFieldInput({
  className,
  ...props
}: NumberFieldPrimitive.Input.Props) {
  return (
    <NumberFieldPrimitive.Input
      data-slot="input-group-control"
      className={cn(
        "border-transparent focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 h-8 px-2.5 py-1 text-base transition-[color,box-shadow] duration-200 file:h-6 file:text-sm file:font-medium md:text-sm rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent w-full min-w-0 flex-1 text-center tabular-nums outline-none placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    />
  )
}

function NumberFieldDecrement({
  children,
  "aria-label": ariaLabel = "Decrease",
  ...props
}: NumberFieldPrimitive.Decrement.Props) {
  return (
    <InputGroupAddon align="inline-start">
      <NumberFieldPrimitive.Decrement
        data-slot="number-field-decrement"
        aria-label={ariaLabel}
        render={<InputGroupButton size="icon-xs" />}
        {...props}
      >
        {children ?? <MinusIcon aria-hidden="true" />}
      </NumberFieldPrimitive.Decrement>
    </InputGroupAddon>
  )
}

function NumberFieldIncrement({
  children,
  "aria-label": ariaLabel = "Increase",
  ...props
}: NumberFieldPrimitive.Increment.Props) {
  return (
    <InputGroupAddon align="inline-end">
      <NumberFieldPrimitive.Increment
        data-slot="number-field-increment"
        aria-label={ariaLabel}
        render={<InputGroupButton size="icon-xs" />}
        {...props}
      >
        {children ?? <PlusIcon aria-hidden="true" />}
      </NumberFieldPrimitive.Increment>
    </InputGroupAddon>
  )
}

export {
  NumberField,
  NumberFieldDecrement,
  NumberFieldIncrement,
  NumberFieldInput,
}
